import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const data = JSON.parse(readFileSync('/usr/share/iso-codes/json/iso_4217.json', 'utf8'))['4217'];
const codes = [...new Set(data.map((entry) => entry.alpha_3).filter(Boolean))].sort();
const digitsByCode = [];
const symbolOverrides = [];
for (const code of codes) {
  const output = execFileSync('/workspace/dataset/test10_executable', ['--amount', '1.2345', '--currency', code], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trimEnd();
  const nbSpaceIndex = output.indexOf('\u00a0');
  if (nbSpaceIndex === -1) {
    throw new Error(`No NBSP in output for ${code}: ${JSON.stringify(output)}`);
  }
  const prefix = output.slice(0, nbSpaceIndex);
  const numberPart = output.slice(nbSpaceIndex + 1);
  const fractional = numberPart.includes('.') ? numberPart.split('.')[1].length : 0;
  if (fractional !== 2) {
    digitsByCode.push([code, fractional]);
  }
  if (prefix !== code) {
    symbolOverrides.push([code, prefix]);
  }
}
console.log('CODES');
console.log(codes.join(' '));
console.log('DIGITS');
for (const [code, digits] of digitsByCode) {
  console.log(`${code} ${digits}`);
}
console.log('SYMBOLS');
for (const [code, prefix] of symbolOverrides) {
  console.log(`${code} ${JSON.stringify(prefix)}`);
}
